const leaderboardClient=new LeaderboardClient();
let rankedChallenge=null,replayRecorder=null,rankedNoticeShown=false,starting=false,pauseAfterStart=false,voyageGeneration=0,rankedResult=null;
leaderboardClient.retryPending().then(results=>{const failed=results.filter(result=>result.status==='rejected');const notice=$('recovery-status');if(notice&&failed.length)notice.textContent=failed.map(result=>`A previous voyage was not saved: ${result.reason.message}`).join(' ');});
function rankMode(text){const el=$('rank-mode');if(el)el.textContent=text;}
function requestReset(){
 if(starting||!visualsReady)return;
 starting=true;pauseAfterStart=false;state='starting';clearControls();unlockSound();soundscape.pause();
 $('start').disabled=true;$('again').disabled=true;$('restart').disabled=true;rankMode('Connecting…');
 const generation=++voyageGeneration;
 // A static-only host remains playable, but is explicitly a practice game.
 const begin=leaderboardClient.begin();
 const complete=challenge=>{
  if(generation!==voyageGeneration)return;
  starting=false;$('start').disabled=false;$('restart').disabled=false;$('again').disabled=false;
  reset(challenge);if(pauseAfterStart||document.hidden)autoPause();
 };
 if(begin&&typeof begin.then==='function')begin.then(complete,()=>complete(null));else complete(begin);
}
function animateLiveEntry(options={}){
 return animateLeaderboardEntry($('score-report'),{...options,announcementText:rankedResult?.entry?`Your voyage ranks ${rankedResult.entry.rank} of ${rankedResult.board.total}.`:null});
}
function renderRankedResult(generation){
 if(generation!==voyageGeneration||!rankedResult)return;
 scoreEntry?.cancel();scoreEntry=null;
 renderLiveScoreReport($('score-report'),run,rankedResult);
 const retry=$('score-report').querySelector?.('.rank-retry');
 if(retry)retry.onclick=()=>saveRankedResult(generation);
 if(scoreRevealed)scoreEntry=animateLiveEntry({waitForVisibility:!celebrationResults});
}
function saveRankedResult(generation){
 if(generation!==voyageGeneration||!rankedResult?.pending)return;
 const item=rankedResult.pending;
 rankedResult.state='saving';rankedResult.message=null;renderRankedResult(generation);
 leaderboardClient.submit(item).then(result=>{
  if(generation!==voyageGeneration)return;
  rankedResult={state:'saved',board:result.board,entry:result.entry,verifiedRun:result.verifiedRun};renderRankedResult(generation);
 },error=>{
  if(generation!==voyageGeneration)return;
  const terminal=error.status>=400&&error.status<500&&error.status!==429;
  rankedResult.state=terminal?'rejected':'pending';
  rankedResult.message=terminal?'This voyage could not be ranked. Please start a new voyage.':item.persisted?'Not saved yet. Your replay is kept in this browser for another attempt. Retry while the ticket is valid.':'Not saved yet. Browser storage is unavailable. Keep this tab open and retry saving.';
  renderRankedResult(generation);
 });
}
function finishRanking(){
 const generation=voyageGeneration,replay=replayRecorder?.snapshot();
 rankedResult={state:'practice',message:replayRecorder?.error||null};
 if(rankedChallenge&&replay){
  rankedResult={state:'saving',pending:leaderboardClient.queue(rankedChallenge,run.playerName,replay)};
  saveRankedResult(generation);
 }else{
  renderRankedResult(generation);
  leaderboardClient.board().then(board=>{if(generation===voyageGeneration&&rankedResult?.state==='practice'){rankedResult.board=board;renderRankedResult(generation);}},()=>{});
 }
}

