function setVisualMode(mode){visualMode=mode==='A'?'A':'B';const enhanced=visualMode==='B';sea.visible=!enhanced;ocean.setEnabled(enhanced);ocean.reset();atmosphere.setEnabled(enhanced);scene.background.set(enhanced?'#a6b7bf':'#9cbdc8');scene.fog.color.set(enhanced?'#a6b7bf':'#9cbdc8');scene.fog.density=enhanced?.0018:.0027;hemisphere.intensity=enhanced?1.35:2;hemisphere.color.set(enhanced?'#d5e8f0':0xc7e8e7);hemisphere.groundColor.set(enhanced?'#47535b':0x233330);sun.color.set(enhanced?'#ffe0ad':0xffeac2);sun.intensity=enhanced?3.4:3.2;sun.castShadow=enhanced;if(renderer.shadowMap){renderer.shadowMap.enabled=enhanced;renderer.shadowMap.type=THREE.PCFSoftShadowMap;}renderer.toneMappingExposure=enhanced?1.05:1.15;if(!enhanced){sun.position.set(-80,150,80);sun.target.position.set(0,0,0);}for(const e of effects){scene.remove(e.mesh);e.mesh.geometry.dispose();e.mesh.material.dispose();}effects.length=0;ship.traverse(o=>{if(o.isMesh){o.castShadow=enhanced;o.receiveShadow=enhanced;}});}
