function animateCaptain(dt){captainAnimationState.state=state;captainAnimationState.speech=Math.max(0,Math.min(1,trumpReactUntil-time));captainAnimator.update(dt,time,captainAnimationState);}
function attachCaptainModel(model){captainAnimator=installCaptainModel({holder:captain,model,previousAnimator:captainAnimator,arms:captainArms,enhanced:visualMode==='B'});}
async function loadShipAssets(){
  if(typeof window==='undefined')return;
  const startButton=$('start');startButton.disabled=true;startButton.firstChild.textContent='Loading ship and captain… ';
  try{
    const loader=new GLTFLoader();
    const captainLoad=loadOptionalCaptain(loader);
    const [asset,captainAsset]=await Promise.all([loader.loadAsync('./ship-v3.glb'),captainLoad]);
    for(const part of proceduralShipParts)ship.remove(part);
    exteriorModel=asset.scene;exteriorModel.traverse(o=>{if(o.isMesh){o.castShadow=visualMode==='B';o.receiveShadow=visualMode==='B';}});ship.add(exteriorModel);
    let captainLoaded=false;
    if(captainAsset)try{attachCaptainModel(captainAsset.scene);captainLoaded=true;}catch(error){console.warn('Captain rig invalid; using original character.',error);}
    if(!captainLoaded)toast('The new captain did not load. Play with the original character or refresh.');
    visualsReady=true;startButton.disabled=false;startButton.firstChild.textContent='Start voyage ';
  }catch(error){$('fallback').classList.remove('hidden');$('fallback').querySelector('h2').textContent='The ship did not load';$('fallback').querySelector('p').textContent='The ship model could not load. Try refreshing the page.';console.error('Ship asset failed to load',error);}
}
loadShipAssets();
